import React, { useState } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  TextField,
  Button,
  InputAdornment,
  IconButton,
  Alert,
  CircularProgress
} from '@mui/material';
import {
  Visibility,
  VisibilityOff,
  Mail,
  Lock
} from '@mui/icons-material';

// Split Auth Layout Component
const SplitAuthLayout = ({ children }) => {
  return (
    <Box
      sx={{
        minHeight: '100vh',
        display: 'flex',
        fontFamily: 'system-ui, -apple-system, sans-serif',
      }}
    >
      {children}
    </Box>
  );
};

// Left Brand Panel Component
const LeftBrandPanel = () => {
  return (
    <Box
      sx={{
        width: { xs: '0%', md: '50%' },
        height: '100vh',
        background: 'linear-gradient(135deg, #2563eb 0%, #1e40af 100%)',
        display: { xs: 'none', md: 'flex' },
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        position: 'relative',
        p: 6,
        color: 'white',
      }}
    >
      <Box sx={{ textAlign: 'center', maxWidth: '400px', zIndex: 1 }}>
        <Typography
          variant="h2"
          sx={{
            fontWeight: 700,
            mb: 2,
            fontSize: '2.5rem',
            lineHeight: '1.2',
          }}
        >
          Site Survey Tool
        </Typography>

        <Typography
          variant="h6"
          sx={{
            fontWeight: 400,
            mb: 8,
            fontSize: '1.125rem',
            opacity: 0.9,
            lineHeight: '1.6',
          }}
        >
          ISP Site Survey Management System
        </Typography>

        {/* Center Illustration */}
        <Box
          sx={{
            width: '180px',
            height: '180px',
            backgroundColor: 'rgba(255, 255, 255, 0.1)',
            borderRadius: '50%',
            mx: 'auto',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            mb: 8,
            fontSize: '4rem',
          }}
        >
          📐
        </Box>

        <Typography
          variant="body1"
          sx={{
            fontSize: '1rem',
            opacity: 0.8,
            lineHeight: '1.6',
          }}
        >
          Professional site survey management for ISP infrastructure
        </Typography>
      </Box>

      {/* Decorative Elements */}
      <Box
        sx={{
          position: 'absolute',
          top: '-100px',
          right: '-100px',
          width: '300px',
          height: '300px',
          backgroundColor: 'rgba(255, 255, 255, 0.05)',
          borderRadius: '50%',
        }}
      />
      <Box
        sx={{
          position: 'absolute',
          bottom: '-150px',
          left: '-150px',
          width: '400px',
          height: '400px',
          backgroundColor: 'rgba(255, 255, 255, 0.03)',
          borderRadius: '50%',
        }}
      />
    </Box>
  );
};

// Auth Card Component
const AuthCard = ({ children }) => {
  return (
    <Card
      sx={{
        maxWidth: '380px',
        width: '100%',
        backgroundColor: '#ffffff',
        borderRadius: '16px',
        boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06)',
        border: '1px solid #f1f5f9',
      }}
    >
      <CardContent sx={{ p: 5 }}>
        {children}
      </CardContent>
    </Card>
  );
};

// Demo Credentials Box Component
